import { readFileSync } from 'node:fs';
function parse(file) {
  let css = readFileSync(file, 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
  const out = new Map();
  // flatten: handle nested @media by just walking braces
  const re = /([^{}]+)\{([^{}]*)\}/g;
  let m;
  while ((m = re.exec(css))) {
    const sel = m[1].trim().replace(/\s+/g, ' ');
    const decls = m[2].split(';').map(s => s.trim()).filter(s => /^(font|line-height)/.test(s));
    if (decls.length) {
      const prev = out.get(sel) || [];
      out.set(sel, prev.concat(decls));
    }
  }
  return out;
}
const pre = parse(process.argv[2]), now = parse(process.argv[3]);
const sels = new Set([...pre.keys(), ...now.keys()]);
for (const s of sels) {
  const a = (pre.get(s) || []).join('; '), b = (now.get(s) || []).join('; ');
  console.log(`${s}\n    PRE: ${a || '(none)'}\n    NOW: ${b || '(none)'}`);
}
