/* Body, text/primary. One line, always: 40 characters is a contract with the
   agent, and all the card can do is stop a long one from breaking the layout
   -- the full sentence lives in the expansion. */
.current-setup-title {
.message.note {
  align-self: stretch;
  max-width: 100%;
  padding: 4px 0;
  color: var(--text-secondary);
  font: var(--font-body);
  background: none;
.revision-marker {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  align-self: stretch;
  padding: 4px 8px;
  border-left: 3px solid var(--border-strong);
  font: var(--font-body);
  color: var(--text-secondary);
}

}

/* A slice warning is the most actionable line on the card, so it takes Label
   rather than the Dense Metadata its sibling provenance line uses. */
.history-warnings {
  padding-left: 20px;
  color: var(--status-warning);
  font: var(--font-label);
}
button.primary {
  padding: 8px 16px;
  border-radius: var(--radius-compact);
  background: var(--action-primary);
  color: var(--action-primaryText);
}

button.link {
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: var(--action-primary);
}

.setup-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-subtle);
  color: var(--status-success);
  font: var(--font-body);
}

.setup-path {
  width: 100%;
  margin: 0;
  padding: 8px 12px;
  border-radius: var(--radius-standard);
  background: var(--surface-subtle);
  font: var(--font-body);
  overflow-wrap: anywhere;
}

.setup-diff {
}

/* Native tool action cards. The title inherits Body from the card. */
.tool-card {
  align-self: stretch;
  margin-left: 12px;
  padding: 8px 12px;
  border: 1px solid var(--border-subtle);
  border-left: 3px solid var(--action-primary);
  border-radius: var(--radius-container);
  background: var(--surface-raised);
}

.tool-card .tool-meta {
  font: var(--font-metadata);

button.danger { color: var(--status-danger); }
.chat-list-pane { display: flex; flex-direction: column; flex: 1; min-height: 0; background: var(--surface-canvas); }
.chat-list-header { height: 56px; padding: 12px 16px; }
.chat-list-header .chat-icon { border: 0; }
.chat-list-scroll { flex: 1; min-height: 0; overflow-y: auto; }
.chat-list-empty { margin: 16px; color: var(--text-secondary); font: var(--font-body); }
button.chat-list-row {
  display: block;
  width: 100%;
  min-height: 64px;
  padding: 12px 16px;
---
.chat-dialog label { display: block; font: var(--font-label); }
.chat-dialog input { width: 100%; margin-top: 4px; padding: 8px; font: inherit; color: var(--text-primary); background: var(--surface-canvas); border: 1px solid var(--border-strong); border-radius: var(--radius-standard); }
.chat-dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }
.chat-error { display: flex; align-items: center; gap: 8px; flex: 0 0 auto; padding: 8px 12px; font: var(--font-body); color: var(--status-danger); background: var(--surface-raised); border-bottom: 1px solid var(--border-subtle); }
.chat-error span { flex: 1; }
---
  display: block;
  height: 100%;
  background: var(--status-danger);
}

.setup-kicker {
  display: flex;
  align-items: center;
  gap: 8px;
  font: var(--font-label);
  color: var(--status-success);
}

---
/* Every color, radius, and type metric below resolves through a custom
   property that tokens.ts writes from resources/jusprin/ui/design-tokens.json:
   --<group>-<name> for colors, --radius-<name> for radii, --font-<role> and
   --font-mono-<role> for the `font` shorthand of each type role. Padding,
   margin, and gap stay literal but must sit on the spacing scale. styles.test.ts
   fails the build on any literal outside those rules. */

